// Package secretmask detects credential-shaped strings in arbitrary byte
// buffers using a single compiled DFA.
//
// The DFA is generated by Ragel from rules.rl and checked in as
// rules_ragel.go; the rule metadata that goes with it lives in this file.
// Both sides must agree on the RuleID set, and TestRuleMetadataComplete
// enforces that by requiring one positive sample per rule.
//
// # Layering
//
// This package implements the lexical layer only: it answers "does this byte
// range look like credential shape X". Per-rule length bounds are applied
// here because a DFA cannot express them cheaply; everything else that needs
// native code (entropy, checksums, base64/JWT decoding, surrounding-keyword
// context) is deliberately not part of this layer yet.
//
// # Why one DFA
//
// Running N independent regexes over a buffer costs O(N x len); a single DFA
// costs O(len). The generated machine is compiled with the goto-driven code
// style, which trades code size and compile time for run time.
//
// # Rule encoding
//
// Every rule body is written as prefix + charset+ and its length is checked
// in collector.emit. Encoding lengths into the machine with {n,m} or {n,}
// costs an order of magnitude more DFA states, makes the generated code
// ~10x larger, and measurably slows the match loop down; see rules.rl.
package secretmask

// RuleID identifies one credential shape recognized by the compiled DFA.
// RuleUnknown is the zero value and never matches.
type RuleID uint16

// Kind is the credential category a caller usually branches on. Vendor
// disambiguation happens outside this package, from surrounding context.
type Kind uint8

const (
	KindUnknown Kind = iota
	KindPrivateKey
	KindJSONWebToken
	KindAPIKey
	KindOAuthToken
	KindOAuthClientSecret
	KindAccessToken
	KindRefreshToken
	KindAccessKeyID
	KindWebhookSecret
	KindPersonalAccessToken
	KindServiceAccountKey
	KindSessionKey
	KindEphemeralKey
	KindGenericKey
)

// Grade records how strong the format evidence is, following the grading used
// by the format reference: A means an official document states the shape, D
// means the shape rests on community observation. Where that reference grades
// a prefix and a length separately, this field carries the weaker of the two.
type Grade uint8

const (
	GradeUnknown Grade = iota
	GradeA
	GradeB
	GradeC
	GradeD
)

// Rule is the static metadata attached to a RuleID.
type Rule struct {
	// Name is a stable identifier such as "anthropic.api_key". It is part of
	// the package API: callers persist and match on it.
	Name string
	// Vendor is the issuing organization, empty for vendor-neutral shapes.
	Vendor string
	Kind   Kind
	Grade  Grade
	// MinLen and MaxLen bound the total match length in bytes, inclusive.
	// MaxLen 0 means unbounded.
	MinLen int
	MaxLen int
}

